sys_script_include.script:
var Testutils = Class.create();
Testutils.prototype = {
    initialize: function() {
    },
    getDateTest: function() {
        var beginToday = gs.beginningOfToday(); 
        var endToday = gs.endOfToday(); 
        var beginTomorrow = gs.beginningOfTomorrow(); 
        var endTomorrow = gs.endOfTomorrow(); 
        var beginYesterday = gs.beginningOfYesterday(); 
        var endYesterday = gs.endOfYesterday(); 

        gs.info('beginningOfToday: ' + beginToday); 
        gs.info('endOfToday: ' + endToday); 
        gs.info('-----------'); 
        gs.info('beginningOfTomorrow: ' + beginTomorrow); 
        gs.info('endOfTomorrow: ' + endTomorrow); 
        gs.info('beginningOfYesterday: ' + beginYesterday); 
        gs.info('endOfYesterday: ' + endYesterday); 
        gs.info('-----------'); 
        var gdt1 = new GlideDateTime(beginToday); 
        var gdt2 = new GlideDateTime(beginTomorrow); 
        var dur = GlideDateTime.subtract(gdt1, gdt2); //the difference between gdt1 and gdt2 
        gs.info('BeginTomorrow: ' + dur.getDisplayValue()); 

        var gdt3 = new GlideDateTime(endToday); 
        var gdt4 = new GlideDateTime(endTomorrow); 
        var dur1 = GlideDateTime.subtract(gdt4, gdt3); //the difference between gdt1 and gdt2 
        gs.info('EndTomorrow: ' + dur1.getDisplayValue()); 

        var gdt5 = new GlideDateTime(beginToday); 
        var gdt6 = new GlideDateTime(beginYesterday); 
        var dur2 = GlideDateTime.subtract(gdt6, gdt5); //the difference between gdt1 and gdt2 
        gs.info('BeginningYesterday: ' + dur2.getDisplayValue()); 

        var gdt7 = new GlideDateTime(endToday); 
        var gdt8 = new GlideDateTime(endYesterday); 
        var dur3 = GlideDateTime.subtract(gdt8, gdt7); //the difference between gdt1 and gdt2 
        gs.info('EndYesterday: ' + dur3.getDisplayValue());

    },
    type: 'Testutils'
};
